functions.vm_camera_move_to:
static void vm_camera_move_to(SCRIPT_CTX * THIS, INT16 idx, UBYTE speed, UBYTE after_lock_camera) {


    camera_position_t * params;
    UBYTE x_dest;
    THIS->waitable = 1;

    params = VM_REF_TO_PTR(idx);


    camera_settings &= ~(CAMERA_LOCK_FLAG);


    if ((camera_x == params->X) && (camera_y == params->Y)) {
        camera_settings = after_lock_camera;
        camera_clamp_x = camera_x;
        camera_clamp_y = camera_y;
        return;
    }


    x_dest = FALSE;
    if (camera_x > params->X) {

        camera_x -= speed;
        if (camera_x <= params->X) {
            camera_x = params->X;
            x_dest = TRUE;
        }
    } else if (camera_x < params->X) {

        camera_x += speed;
        if (camera_x >= params->X) {
            camera_x = params->X;
            x_dest = TRUE;
        }
    }

    if (camera_y > params->Y) {

        camera_y -= speed;
        if (camera_y <= params->Y) {
            camera_y = params->Y;
            if (x_dest) {
                return;
            }
        }
    } else if (camera_y < params->Y) {

        camera_y += speed;
        if (camera_y >= params->Y) {
            camera_y = params->Y;
            if (x_dest) {
                return;
            }
        }
    }

    THIS->PC -= 5u;
    return;
}

