functions.camera_shake_frames:
static UBYTE camera_shake_frames(void * THIS, UBYTE start, UWORD * stack_frame) {
    if (start) *((SCRIPT_CTX *)THIS)->stack_ptr = sys_time;
    if (((UWORD)((UWORD)sys_time - *((SCRIPT_CTX *)THIS)->stack_ptr)) < stack_frame[0]) {
        if (stack_frame[1] & CAMERA_SHAKE_X) {
            scroll_offset_x = (ngc_rand() % (stack_frame[2] << 1)) - stack_frame[2];
        }
        if (stack_frame[1] & CAMERA_SHAKE_Y) {
            scroll_offset_y = (ngc_rand() % (stack_frame[2] << 1)) - stack_frame[2];
        }
        ((SCRIPT_CTX *)THIS)->waitable = TRUE;
        return FALSE;
    }
    scroll_offset_x = scroll_offset_y = 0;
    return TRUE;
}

