static void vm_switch(SCRIPT_CTX * THIS, INT16 idx, UBYTE size, UBYTE n) {
    INT16 value;
    const UBYTE * table;

    if (idx < 0) value = *(THIS->stack_ptr + idx); else value = *(script_memory + idx);
    if (n) THIS->stack_ptr -= n;        

    SWITCH_ROM(THIS->bank);             

    table = THIS->PC;
    while (size) {
        if (value == NGC_LE16(table)) {
            THIS->PC = ngc_banks[THIS->bank] + (UWORD)NGC_LE16(table + 2);   
            return;
        } else table += 4;
        size--;
    }

    THIS->PC = table;          
}

