vm_rpn.text:
static void vm_rpn(SCRIPT_CTX * THIS) {

    INT16 * A, * B, * ARGS;
    INT16 idx;
    const UBYTE * pc;
    UWORD * sp;

    SWITCH_ROM(THIS->bank);             

    pc = THIS->PC;
    sp = THIS->stack_ptr;
    ARGS = sp;
    while (TRUE) {
        INT8 op;
        op = *(pc++);
        if (op < 0) {
            switch (op) {

case VM_OP_REF_MEM_IND:
    op = *(pc++);
    idx = NGC_LE16(pc);
    idx = *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx);
    switch ((UINT8)op) {
        case VM_OP_MEM_I8  : *(sp) = *((INT8 *)(ngc_banks[THIS->bank] + (UWORD)idx));  break;
        case VM_OP_MEM_U8  : *(sp) = *((UINT8 *)(ngc_banks[THIS->bank] + (UWORD)idx)); break;
        case VM_OP_MEM_I16 : *(sp) = NGC_LE16(ngc_banks[THIS->bank] + (UWORD)idx); break;
    }
    pc += 2;
    break;

case VM_OP_REF_MEM_SET:
    op = *(pc++);
    switch ((UINT8)op) {
        case VM_OP_MEM_I8  : *((INT8 *)ngc_memory(NGC_LE16(pc)))  = *(--(sp)); break;
        case VM_OP_MEM_U8  : *((UINT8 *)ngc_memory(NGC_LE16(pc))) = *(--(sp)); break;
        case VM_OP_MEM_I16 : *((INT16 *)ngc_memory(NGC_LE16(pc))) = *(--(sp)); break;
    }
    pc += 2;
    continue;

case VM_OP_REF_MEM:
    op = *(pc++);
    switch ((UINT8)op) {
        case VM_OP_MEM_I8  : *(sp) = *((INT8 *)ngc_memory(NGC_LE16(pc)));  break;
        case VM_OP_MEM_U8  : *(sp) = *((UINT8 *)ngc_memory(NGC_LE16(pc))); break;
        case VM_OP_MEM_I16 : *(sp) = *((INT16 *)ngc_memory(NGC_LE16(pc))); break;
    }
    pc += 2;
    break;

case VM_OP_REF_SET_IND:
    idx = NGC_LE16(pc);
    idx = *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx);
    *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx) = *(--(sp));
    pc += 2;
    continue;

case VM_OP_REF_SET:
    idx = NGC_LE16(pc);
    *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx) = *(--(sp));
    pc += 2;
    continue;

case VM_OP_REF_IND:
    idx = NGC_LE16(pc);
    idx = *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx);
    *(sp) = *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx);
    pc += 2;
    break;

case VM_OP_REF:
    idx = NGC_LE16(pc);
    *(sp) = *((idx < 0) ? ARGS + idx : (INT16 *)script_memory + idx);
    pc += 2;
    break;

        default:
            { THIS->PC = pc; THIS->stack_ptr = sp; return; }
    }
    sp++;
} else {
    A = sp - 2; B = A + 1;
    switch ((UINT8)op) {

                default:
                    { THIS->PC = pc; THIS->stack_ptr = sp; return; }
            }
            sp--;
        }
    }
}

