static UBYTE script_terminate(UBYTE ID) {
    static SCRIPT_CTX * ctx;
    ctx = first_ctx;
    while (ctx) {
        if (ctx->ID == ID) {
            if (ctx->hthread) {
                *(ctx->hthread) |= SCRIPT_TERMINATED;
                ctx->hthread = 0;
            }
            return ctx->terminated = TRUE;
        } else ctx = ctx->next;
    }
    return FALSE;
}

functions.script_runner_init:
static void script_runner_init(UBYTE reset) {
    UWORD * base_addr;
    SCRIPT_CTX * nxt;
    SCRIPT_CTX * tmp;
    UBYTE i;
    if (reset) {
        ngc_clear((UBYTE *)script_memory, sizeof(script_memory));
        ngc_clear((UBYTE *)CTXS, sizeof(CTXS));
    }
    base_addr = &script_memory[VM_HEAP_SIZE];
    free_ctxs = CTXS, first_ctx = 0;
    nxt = 0;
    tmp = CTXS + (VM_MAX_CONTEXTS - 1);
    for (i = VM_MAX_CONTEXTS; i != 0; i--) {
        tmp->next = nxt;
        tmp->base_addr = base_addr;
        tmp->ID = i;
        base_addr += VM_CONTEXT_STACK_SIZE;
        nxt = tmp--;
    }
    vm_lock_state = 0;
    vm_loaded_state = FALSE;

    old_executing_ctx = 0, executing_ctx = first_ctx;
}

functions.script_execute:
static SCRIPT_CTX * script_execute(UBYTE bank, UBYTE * pc, UWORD * handle, UBYTE nargs) {
    SCRIPT_CTX * tmp;
    if (free_ctxs == NULL) return NULL;
#ifdef SAFE_SCRIPT_EXECUTE
    if (pc == NULL) return NULL;
#endif

    tmp = free_ctxs;

    free_ctxs = free_ctxs->next;

    tmp->PC = pc, tmp->bank = bank, tmp->stack_ptr = tmp->base_addr;

    tmp->hthread = handle;
    if (handle) *handle = tmp->ID;

    tmp->terminated = FALSE;

    tmp->lock_count = 0;

    tmp->flags = 0;

    tmp->update_fn = 0; tmp->update_fn_bank = 0;

    tmp->next = NULL;
    if (first_ctx) {
         SCRIPT_CTX * idx = first_ctx;
         while (idx->next) idx = idx->next;
         idx->next = tmp;
    } else first_ctx = tmp;

    (void)nargs;

    return tmp;
}

functions.script_runner_update:
UBYTE script_runner_update(void) {
    UBYTE waitable;
    UBYTE counter;
    FASTUBYTE _save;
    SCRIPT_CTX * ctx;
    SCRIPT_CTX * old;

    _save = CURRENT_BANK;


    ctx = executing_ctx;
    old = old_executing_ctx;
    if (!vm_lock_state) old = 0, ctx = first_ctx;

    waitable = TRUE;
    counter = INSTRUCTIONS_PER_QUANT;
    while (ctx) {
        vm_exception_code = EXCEPTION_CODE_NONE;
        ctx->waitable = FALSE;
        if ((ctx->terminated != FALSE) || (!VM_STEP(ctx))) {

            vm_lock_state -= ctx->lock_count;

            if (ctx->hthread) *(ctx->hthread) |= SCRIPT_TERMINATED;

            if (old) old->next = ctx->next;
            if (first_ctx == ctx) first_ctx = ctx->next;

            ctx->next = free_ctxs, free_ctxs = ctx;

            if (old) ctx = old->next; else ctx = first_ctx;
        } else {

            if (vm_exception_code) {
                old_executing_ctx = old, executing_ctx = ctx;
                SWITCH_ROM(_save);
                return RUNNER_EXCEPTION;
            }

            if (!(ctx->waitable) && (counter--)) continue;

            if (vm_lock_state) break;

            waitable &= ctx->waitable;
            old = ctx, ctx = ctx->next;
            counter = INSTRUCTIONS_PER_QUANT;
        }
    }
    old_executing_ctx = old, executing_ctx = ctx;
    SWITCH_ROM(_save);


    if (first_ctx == 0) return RUNNER_DONE;

    if (waitable) return RUNNER_IDLE; else return RUNNER_BUSY;
}

