functions.timers_init:
static void timers_init(UBYTE preserve) {
    UBYTE i;
    if (preserve) {
        for (i = 0; i != MAX_CONCURRENT_TIMERS; i++)
            timer_events[i].handle = 0;
    } else {
        ngc_clear((UBYTE *)timer_values, sizeof(timer_values));
        ngc_clear((UBYTE *)timer_events, sizeof(timer_events));
    }
}

functions.timers_update:
void timers_update(void) {
    timer_time_t * ctimer = timer_values;
    UBYTE i;
    script_event_t * event;
    for (i = 0; i != MAX_CONCURRENT_TIMERS; i++) {
        if (ctimer->value) {
            if (--ctimer->remains == 0) {
                ctimer->remains = ctimer->value;
                event = &timer_events[i];
                if (!event->script_addr) continue;
                if ((event->handle == 0) || ((event->handle & SCRIPT_TERMINATED) != 0)) {
                    script_execute(event->script_bank, event->script_addr, &event->handle, 0);
                }
            }

        }
        ctimer++;
    }
}

