static void events_init(UBYTE preserve) {
    UBYTE i;
    if (preserve) {
        for (i = 0; i < 8; i++)
            input_events[i].handle = 0;
    } else {
        ngc_clear((UBYTE *)input_slots, sizeof(input_slots));
        ngc_clear((UBYTE *)input_events, sizeof(input_events));
    }
}

functions.events_update:
void events_update(void) {
    UBYTE * slot_ptr = input_slots;
    UBYTE tmp, key;
    script_event_t * event;
    SCRIPT_CTX * ctx;
    for (tmp = ngc_joy, key = 1; (tmp); tmp = tmp >> 1, key = key << 1, slot_ptr++) {
        if (tmp & 1) {
            if (*slot_ptr == 0) continue;
            event = &input_events[(*slot_ptr & 0x0f) - 1u];
            if (!event->script_addr) continue;
            if (*slot_ptr & 0x80) { ngc_joy ^= key; ngc_joy_pressed &= (UBYTE)~key; }     
            if (ngc_last_joy & key) continue;
            if ((event->handle == 0) || ((event->handle & SCRIPT_TERMINATED) != 0))
                { ctx = script_execute(event->script_bank, event->script_addr, &event->handle, 0);
                  if (ctx) *(ctx->stack_ptr++) = (UWORD)key; }
        }
    }
    ngc_recent_joy = ngc_recent_joy & ngc_joy;
}

