functions.ui_draw_text_buffer_char:
static UBYTE ui_draw_text_buffer_char(void) {
    static UBYTE current_font_idx, current_text_bkg_fill, current_vwf_direction, current_text_ff_joypad, current_text_draw_speed;

    if (ui_text_ptr == 0) {

        current_text_speed = ui_time_masks[text_draw_speed];

        current_font_idx        = vwf_current_font_idx;
        current_text_bkg_fill   = text_bkg_fill;
        current_vwf_direction   = vwf_direction;
        current_text_ff_joypad  = text_ff_joypad;
        current_text_draw_speed = text_draw_speed;


        ui_text_ptr = ui_text_data;

        if ((text_options & TEXT_OPT_PRESERVE_POS) == 0) {
            ui_dest_base = text_render_base_addr + 32 + 1;                  
            if (vwf_direction == UI_PRINT_RIGHTTOLEFT) ui_dest_base += 17;  

            ui_dest_ptr = ui_dest_base;

            ui_print_reset();
        }
    }


    while (TRUE) {
        switch (*ui_text_ptr) {
            case 0x00: {
                ui_text_ptr = 0;
                text_drawn = TRUE;
                if (vwf_current_font_idx != current_font_idx) {
                    ngc_ui_font_load(vwf_current_font_idx);
                }
                text_bkg_fill = current_text_bkg_fill;
                vwf_direction = current_vwf_direction;
                text_ff_joypad = current_text_ff_joypad;
                text_draw_speed = current_text_draw_speed;
                return FALSE;
            }
            case 0x01:

                text_draw_speed = (*(++ui_text_ptr) - 1u) & 0x07u;
                current_text_speed = ui_time_masks[text_draw_speed];
                break;
            case 0x02: {

                UBYTE old_flags;
                current_font_idx = *(++ui_text_ptr) - 1u;
                old_flags = vwf_current_font_desc.attr;
                ngc_ui_font_load(current_font_idx);
                if ((vwf_current_offset) && ((old_flags & FONT_VWF) != 0) && ((vwf_current_font_desc.attr & FONT_VWF) == 0)) {
                    ui_dest_ptr++;
                }
                break;
            }
            case 0x03:

                {
                    INT16 gx, gy;
                    gx = (INT16)*++ui_text_ptr - 1;
                    gy = (INT16)*++ui_text_ptr - 1;
                    ui_dest_ptr = ui_dest_base = text_render_base_addr + (INT16)(gx + gy * 32);
                }
                if (vwf_current_offset) ui_print_reset();
                break;
            case 0x04: {

                BYTE dx, dy;
                dx = (BYTE)(*++ui_text_ptr);
                if (dx > 0) dx--;
                dy = (BYTE)(*++ui_text_ptr);
                if (dy > 0) dy--;
                ui_dest_base = ui_dest_ptr += (INT16)(dx + dy * 32);
                if (vwf_current_offset) ui_print_reset();
                break;
            }
            case 0x06:

                if (text_ff) {
                    text_ff = FALSE;
                    INPUT_RESET;
                }
                text_ff_joypad = FALSE;

                ui_text_ptr++;

                if (text_draw_speed) {

                    if (INPUT_PRESSED(*ui_text_ptr)) {

                        text_ff_joypad = current_text_ff_joypad;
                        INPUT_RESET;
                    } else {

                        ui_text_ptr--;
                        current_text_speed = 0;
                        return FALSE;
                    }
                }
                current_text_speed = ui_time_masks[text_draw_speed];
                break;
            case 0x07:

                text_bkg_fill = (*++ui_text_ptr & 1u) ? TEXT_BKG_FILL_W : TEXT_BKG_FILL_B;
                break;
            case 0x08:

                vwf_direction = (*++ui_text_ptr & 1u) ? UI_PRINT_LEFTTORIGHT : UI_PRINT_RIGHTTOLEFT;
                break;
            case 0x09:
                break;
            case '\n':  

                ui_dest_ptr = ui_dest_base += 32u;
                if (vwf_current_offset) ui_print_reset();
                break;
            case 0x0b:
                text_palette = (((*++ui_text_ptr) - 1u) & 0x07u);
                break;
            case '\r':  

                if ((UWORD)(ui_dest_ptr - NGC_WIN_MAP + 32) > (UWORD)((((UWORD)(text_scroll_addr - NGC_WIN_MAP) + ((UWORD)text_scroll_height << 5)) & 0xFFE0u) - 1u)) {
                    scroll_rect(text_scroll_addr, text_scroll_width, text_scroll_height, text_scroll_fill);
                    ui_dest_ptr = ui_dest_base;
                } else {
                    ui_dest_ptr = ui_dest_base += 32u;
                }
                if (vwf_current_offset) ui_print_reset();
                break;
            case 0x05:

                ui_text_ptr++;

            default:
                if (ui_print_render(*ui_text_ptr)) {
                    ui_set_tile(ui_dest_ptr, ui_prev_tile, ui_prev_tile_bank);
                    if (vwf_direction == UI_PRINT_LEFTTORIGHT)  ui_dest_ptr++; else ui_dest_ptr--;
                }
                if (vwf_current_offset) ui_set_tile(ui_dest_ptr, ui_current_tile, ui_current_tile_bank);
                ui_text_ptr++;
                return TRUE;
        }
        ui_text_ptr++;
    }
}

functions.ui_update:
static void ui_update(void) {
    UBYTE flag = FALSE;


    if (win_pos_y != win_dest_pos_y) {
        if ((game_time & ui_time_masks[win_speed]) == 0) {
            UBYTE interval = (win_speed == 0) ? 2u : 1u;

            if (win_pos_y < win_dest_pos_y) win_pos_y += interval; else win_pos_y -= interval;
        }
        flag = TRUE;
    }
    if (win_pos_x != win_dest_pos_x) {
        if ((game_time & ui_time_masks[win_speed]) == 0) {
            UBYTE interval = (win_speed == 0) ? 2u : 1u;

            if (win_pos_x < win_dest_pos_x) win_pos_x += interval; else win_pos_x -= interval;
        }
        flag = TRUE;
    }


    if (flag) return;

    if (text_drawn) return;

    if ((text_ff_joypad) && (INPUT_A_OR_B_PRESSED)) {
        text_ff = TRUE;
    } else {
        if (game_time & current_text_speed) return;
    }

    do {
        flag = ui_draw_text_buffer_char();
    } while (((text_ff) || (text_draw_speed == 0)) && (!text_drawn));

    (void)flag;
}

functions.ui_run_modal:
static void ui_run_modal(UBYTE wait_flags) {
    UBYTE fail;
    ngc_input_update();
    do {
        fail = FALSE;

        if (wait_flags & UI_WAIT_WINDOW)
            if ((win_pos_x != win_dest_pos_x) || (win_pos_y != win_dest_pos_y)) fail = TRUE;
        if (wait_flags & UI_WAIT_TEXT)
            if (!text_drawn) fail = TRUE;
        if (wait_flags & UI_WAIT_BTN_A)
            if (!INPUT_A_PRESSED) fail = TRUE;
        if (wait_flags & UI_WAIT_BTN_B)
            if (!INPUT_B_PRESSED) fail = TRUE;
        if (wait_flags & UI_WAIT_BTN_ANY)
            if (!INPUT_ANY_PRESSED) fail = TRUE;

        if (!fail) return;

        ui_update();
#if NGC_TICK_FRAMES == 2
        game_time++;
        ui_update();
        game_time--;
#endif
        ngc_ui_flush();
        ngc_ui_modal_logic();

        game_time += NGC_TICK_FRAMES;
        ngc_vm_frame_end();
        ngc_ui_modal_commit();
        ngc_input_update();
    } while (fail);
}

functions.load_text:
static const unsigned char * load_text(const unsigned char * s, INT16 * args) {
    unsigned char * d = ui_text_data;
    while (*s) {
        if (*s == '%') {
            switch (*++s) {

                case 'D':
                    d += itoa_format(*args, d, *++s - '0');
                    break;

                case 'd':
                    d += itoa_format(*args, d, 0);
                    break;

                case 'c':
                    *d++ = (unsigned char)(*args);
                    break;

                case 't':
                    *d++ = 0x01u;
                    *d++ = (unsigned char)(*args) + 0x02u;
                    break;

                case 'f':
                    *d++ = 0x02u;
                    *d++ = (unsigned char)(*args) + 0x01u;
                    break;

                case '%':
                    s++;
                default:
                    s--;
                    *d++ = *s++;
                    continue;
            }
        } else {
            *d++ = *s++;
            continue;
        }
        s++; args--;
    }
    *d = 0;
    return s + 1;
}

functions.vm_load_text:
static void vm_load_text(SCRIPT_CTX * THIS, UBYTE nargs) {
    const UBYTE * sargs;
    INT16 * dargs;
    SWITCH_ROM(THIS->bank);
    sargs = THIS->PC;
    dargs = (INT16 *)(ui_text_data + (sizeof(ui_text_data) - sizeof(INT16)));
    while (nargs--) {
        *dargs-- = *((INT16 *)VM_REF_TO_PTR(NGC_LE16(sargs)));
        sargs += 2;
    }
    THIS->PC = load_text((const unsigned char *)sargs, (INT16 *)(ui_text_data + (sizeof(ui_text_data) - sizeof(INT16))));
}

